// Pseudo-instrumentation example
function injectContext(msg, span) {
  msg.headers.traceparent = span.toTraceParent();
  msg.headers.tenantId = span.tenantId;
}
function extractContext(msg) {
  return parseTraceParent(msg.headers.traceparent);
}
```

